import {
  Activity, ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Check, ChefHat,
  CircleHelp, Clock3, CookingPot, CreditCard, Eye,
  Flame, ForkKnife, LayoutDashboard, Leaf, LogOut, Minus, Package,
  Plus, Search, Settings2, ShoppingBag, ShoppingCart, Sparkles, Tag, Trash2, TrendingUp,
  UserRound, Utensils, X, Zap,
} from 'lucide-react';
import {
  getGetActiveOrdersQueryKey, getGetAdminDashboardQueryKey, getGetAnalyticsQueryKey,
  getGetOrderQueryKey, getGetOrderStatusQueryKey, getGetReadyTokensQueryKey,
  getGetMenuItemQueryKey, getGetSessionQueryKey, getListAdminOrdersQueryKey, getListMenuQueryKey,
  getListMyOrdersQueryKey, useCreateMenuItem,
  useDeleteMenuItem, useGetActiveOrders, useGetAdminDashboard, useGetAnalytics,
  useGetMenuItem, useGetOrder, useGetOrderStatus, useGetReadyTokens, useGetSession, useHealthCheck, useListAdminOrders,
  useListMenu, useListMyOrders, useLoginAdmin, useLoginCustomer, useLogout,
  usePlaceOrder, useRegisterCustomer, useUpdateMenuItem, useUpdateOrderStatus,
} from '@workspace/api-client-react';

const queryClient = new QueryClient({ defaultOptions: { queries: { retry: 1, staleTime: 15000 } } });
function clearAuthData() { queryClient.clear(); }
const cash = (n: number) => `₹${Number(n || 0).toFixed(2)}`;
const dateShort = (date?: string) => date ? new Date(date).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) : '—';
const timeShort = (date?: string) => date ? new Date(date).toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' }) : '—';
const statusTone: Record<string, string> = {
  PLACED: 'tone-placed', ACCEPTED: 'tone-accepted', PREPARING: 'tone-preparing',
  READY: 'tone-ready', COMPLETED: 'tone-completed', CANCELLED: 'tone-cancelled', REJECTED: 'tone-cancelled',
};
const statusLabel: Record<string, string> = {
  PLACED: 'Placed', ACCEPTED: 'Accepted', PREPARING: 'Cooking', READY: 'Ready for pickup',
  COMPLETED: 'Completed', CANCELLED: 'Cancelled', REJECTED: 'Rejected',
};
type MenuItem = { id: number; name: string; description: string; price: number; category: string; imageUrl?: string | null; isVegetarian: boolean; available: boolean; popular: boolean };
type CartLine = { item: MenuItem; quantity: number };
type CartState = { lines: CartLine[]; add: (item: MenuItem, quantity?: number) => void; change: (id: number, delta: number) => void; clear: () => void; count: number; total: number };
const CartContext = createContext<CartState | null>(null);
function useCart() { const value = useContext(CartContext); if (!value) throw new Error('Cart provider missing'); return value; }
function CartProvider({ children }: { children: ReactNode }) {
  const [lines, setLines] = useState<CartLine[]>(() => { try { return JSON.parse(localStorage.getItem('campusbite-cart') || '[]'); } catch { return []; } });
  useEffect(() => { localStorage.setItem('campusbite-cart', JSON.stringify(lines)); }, [lines]);
  const add = (item: MenuItem, quantity = 1) => setLines((prev) => {
    const found = prev.find((line) => line.item.id === item.id);
    return found ? prev.map((line) => line.item.id === item.id ? { ...line, item, quantity: line.quantity + quantity } : line) : [...prev, { item, quantity }];
  });
  const change = (id: number, delta: number) => setLines((prev) => prev.map((line) => line.item.id === id ? { ...line, quantity: line.quantity + delta } : line).filter((line) => line.quantity > 0));
  const value = useMemo(() => ({ lines, add, change, clear: () => setLines([]), count: lines.reduce((a, l) => a + l.quantity, 0), total: lines.reduce((a, l) => a + l.quantity * Number(l.item.price), 0) }), [lines]);
  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
}

function Shell({ children }: { children: ReactNode }) {
  const [path] = useLocation();
  const cart = useCart(); const { count } = cart;
  const session = useGetSession();
  const logout = useLogout();
  const customerLinks = [
    { href: '/', label: 'Menu', icon: Utensils }, { href: '/orders', label: 'Orders', icon: Package },
    { href: '/profile', label: 'Profile', icon: UserRound },
  ];
  return <div className="min-h-[100dvh] has-mobile-nav">
    <header style={{ background: '#fffdf8ee', backdropFilter: 'blur(14px)', borderBottom: '1px solid #e8dfd1', position: 'sticky', top: 0, zIndex: 30 }}>
      <div className="content-wrap" style={{ height: 72, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <Link href="/" className="brand" style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <span style={{ width: 38, height: 38, background: '#d64e2a', color: '#fff5e5', display: 'grid', placeItems: 'center', borderRadius: 13, transform: 'rotate(-4deg)' }}><ForkKnife size={19}/></span>
          <span style={{ lineHeight: 1 }}><b className="display" style={{ fontSize: 21, letterSpacing: '-.06em' }}>campus<span style={{ color: '#d64e2a' }}>bite</span></b><small style={{ display: 'block', fontSize: 9, color: '#867666', letterSpacing: '.13em', textTransform: 'uppercase', marginTop: 4 }}>good food. no queue.</small></span>
        </Link>
        <nav className="desktop-links" style={{ display: 'flex', alignItems: 'center', gap: 26 }}>
          {customerLinks.slice(0, 2).map((item) => <Link key={item.href} href={item.href} className="navlink" style={{ fontSize: 14, fontWeight: path === item.href ? 800 : 600, color: path === item.href ? '#d64e2a' : '#62584c' }}>{item.label}</Link>)}
          {session.data?.user && <Link href="/profile" className="navlink" style={{ fontSize: 14, color: '#62584c', fontWeight: path === '/profile' ? 800 : 600 }}>{session.data.user.name.split(' ')[0]}</Link>}
          {!session.data?.user ? <Link href="/login" className="btn btn-ink" style={{ padding: '.62rem 1.05rem', fontSize: 13 }}>Sign in <ArrowRight size={15}/></Link> :
            <button className="btn btn-outline" data-testid="button-logout" onClick={() => logout.mutate(undefined, { onSuccess: () => { cart.clear(); clearAuthData(); } })} style={{ padding: '.58rem .9rem', fontSize: 12 }}><LogOut size={14}/> Sign out</button>}
          <Link href="/cart" className="cart-pill" data-testid="link-cart" style={{ background: '#f4ead9', borderRadius: 99, padding: '10px 14px', display: 'flex', gap: 8, alignItems: 'center', fontWeight: 800, fontSize: 13 }}><ShoppingBag size={17}/><span>Cart</span><span style={{ background: '#d64e2a', color: 'white', borderRadius: 99, padding: '2px 7px', fontSize: 11 }}>{count}</span></Link>
        </nav>
        <Link href="/cart" className="mobile-cart" data-testid="link-cart-mobile" style={{ display: 'none', background: '#f4ead9', borderRadius: 99, padding: '9px 12px', alignItems: 'center', gap: 6, fontWeight: 800 }}><ShoppingCart size={18}/>{count}</Link>
      </div>
    </header>
    <main className="page-enter">{children}</main>
    <nav className="mobile-nav">
      {[...customerLinks.slice(0, 2), { href: '/cart', label: 'Cart', icon: ShoppingBag }, customerLinks[2]].map(({ href, label, icon: Icon }) => <Link href={href} key={href} className={path === href ? 'active' : ''} data-testid={`mobile-nav-${label.toLowerCase()}`}><Icon size={19}/><span>{label}</span>{href === '/cart' && count > 0 ? <i style={{ position: 'absolute', background: '#d64e2a', width: 7, height: 7, borderRadius: 8, marginLeft: 20, marginTop: -15 }}/> : null}</Link>)}
    </nav>
  </div>;
}
function PageTitle({ kicker, title, description, right }: { kicker: string; title: string; description?: string; right?: ReactNode }) {
  return <div className="page-title" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'end', gap: 20, margin: '38px 0 28px' }}><div><div className="eyebrow">{kicker}</div><h1 className="display" style={{ fontSize: 'clamp(34px,5vw,54px)', margin: '8px 0 6px', lineHeight: 1.04 }}>{title}</h1>{description && <p style={{ margin: 0, color: '#796d5d' }}>{description}</p>}</div>{right}</div>;
}
function LoadingBlock({ lines = 3 }: { lines?: number }) { return <div style={{ display: 'grid', gap: 12 }}>{Array.from({ length: lines }).map((_, i) => <div key={i} className="skeleton" style={{ height: i ? 65 : 110 }}/>)}</div>; }
function QueryNotice({ error, retry }: { error: unknown; retry: () => void }) { return <div className="surface" style={{ padding: 28, textAlign: 'center' }}><CircleHelp size={28} color="#d64e2a"/><h3 style={{ margin: '10px 0 6px' }}>We couldn't load this just now</h3><p style={{ color: '#786e61' }}>Check your connection and give it another try.</p><button className="btn btn-outline" onClick={retry}>Try again</button></div>; }
function EmptyState({ title, body, href = '/', action = 'Browse the menu' }: { title: string; body: string; href?: string; action?: string }) { return <div className="surface" style={{ padding: '44px 24px', textAlign: 'center' }}><span style={{ width: 56, height: 56, borderRadius: 18, background: '#f8ead3', color: '#c64a28', display: 'grid', placeItems: 'center', margin: '0 auto 14px' }}><ShoppingBag size={25}/></span><h3 className="display" style={{ fontSize: 25, margin: '8px 0' }}>{title}</h3><p style={{ color: '#7b6f60', margin: '0 auto 20px', maxWidth: 360 }}>{body}</p><Link href={href} className="btn btn-primary">{action} <ArrowRight size={16}/></Link></div>; }

const categories = ['All', 'Breakfast', 'Meals', 'Snacks', 'Fast Food', 'Drinks', 'Desserts'];
const categoryTint: Record<string, string> = { Breakfast: '#f4dfaf', Meals: '#e8c4a6', Snacks: '#d9e3c8', 'Fast Food': '#f1c1a7', Drinks: '#d5e2dc', Desserts: '#edd3c9' };
function FoodVisual({ item, size = 'normal' }: { item: MenuItem; size?: 'normal' | 'small' }) {
  if (item.imageUrl) return <img src={item.imageUrl} alt={item.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} data-testid={`img-food-${item.id}`}/>;
  return <div aria-label={item.name} style={{ width: '100%', height: '100%', minHeight: size === 'small' ? 58 : 160, background: `radial-gradient(ellipse at 65% 35%, #fff9e8 0 8%, transparent 9%), radial-gradient(ellipse at 50% 50%, ${categoryTint[item.category] || '#ead9bd'} 0 40%, transparent 41%), linear-gradient(140deg,#f4ead8,#e8dcc8)`, display: 'grid', placeItems: 'center', color: '#6d4b34' }}><span style={{ fontSize: size === 'small' ? 22 : 40, opacity: .55 }}><Utensils size={size === 'small' ? 22 : 38}/></span></div>;
}
function MenuCard({ item }: { item: MenuItem }) {
  const cart = useCart(); const amount = cart.lines.find((line) => line.item.id === item.id)?.quantity || 0; const [showDetails, setShowDetails] = useState(false);
  return <article className="menu-card surface" data-testid={`card-food-${item.id}`} style={{ overflow: 'hidden', borderRadius: 20, position: 'relative' }}>
    <div style={{ height: 170, overflow: 'hidden', background: '#eee2cf', position: 'relative' }}><FoodVisual item={item}/>{item.popular && <span style={{ position: 'absolute', top: 12, left: 12, borderRadius: 99, padding: '6px 9px', background: '#fff9eb', color: '#a7472b', fontSize: 10, fontWeight: 800, letterSpacing: '.05em', display: 'flex', gap: 5, alignItems: 'center' }}><Flame size={12}/> CROWD FAVORITE</span>}<span className={`diet-badge ${item.isVegetarian ? 'diet-veg' : 'diet-nonveg'}`}>{item.isVegetarian ? <><Leaf size={12}/> VEG</> : 'NON-VEG'}</span></div>
    <div style={{ padding: '15px 16px 16px' }}><div style={{ color: '#9b684c', fontSize: 10, letterSpacing: '.13em', textTransform: 'uppercase', fontWeight: 800 }}>{item.category}</div><div style={{ display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'start', marginTop: 5 }}><button className="food-name-button display" onClick={() => setShowDetails(true)}>{item.name}</button><b style={{ whiteSpace: 'nowrap', color: '#28563f' }}>{cash(item.price)}</b></div><p style={{ fontSize: 12, color: '#7d7163', lineHeight: 1.5, minHeight: 37, margin: '8px 0 14px' }}>{item.description}</p>{!item.available ? <button className="btn btn-outline" disabled style={{ width: '100%', padding: '.68rem' }}>Sold out</button> : amount === 0 ? <button className="btn btn-primary add-button" data-testid={`button-add-${item.id}`} onClick={() => cart.add(item)} style={{ width: '100%', padding: '.67rem' }}><Plus size={16}/> Add to order</button> : <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#f6eddf', borderRadius: 99, padding: 4 }}><button aria-label={`Remove one ${item.name}`} className="quantity-button" onClick={() => cart.change(item.id, -1)}><Minus size={15}/></button><span style={{ fontWeight: 800 }}>{amount} in your bag</span><button aria-label={`Add one ${item.name}`} className="quantity-button" onClick={() => cart.add(item)}><Plus size={15}/></button></div>}</div>
    {showDetails && <MenuItemDetail id={item.id} onClose={() => setShowDetails(false)} />}
  </article>;
}
function MenuItemDetail({ id, onClose }: { id: number; onClose: () => void }) {
  const query = useGetMenuItem(id, { query: { queryKey: getGetMenuItemQueryKey(id), enabled: !!id } });
  const cart = useCart();
  const [quantity, setQuantity] = useState(1);
  const item = query.data as MenuItem | undefined;
  return <div className="modal-backdrop" role="presentation" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
    <section className="food-detail-modal" role="dialog" aria-modal="true" aria-label="Dish details">
      <button className="modal-close food-detail-close" aria-label="Close dish details" onClick={onClose}><X size={18}/></button>
      {query.isLoading ? <div className="food-detail-loading"><div className="skeleton" style={{ height: 205 }}/><div className="skeleton" style={{ height: 25 }}/><div className="skeleton" style={{ height: 60 }}/></div> : query.isError || !item ? <div className="food-detail-error"><CircleHelp size={25}/><b>Dish details are unavailable.</b><button className="btn btn-outline" onClick={() => query.refetch()}>Try again</button></div> : <>
        <div className="food-detail-image"><FoodVisual item={item}/></div><div className="food-detail-copy"><span className="eyebrow">{item.category} · {item.isVegetarian ? 'VEGETARIAN' : 'NON-VEGETARIAN'}</span><h2 className="display">{item.name}</h2><p>{item.description}</p><div className="food-detail-bottom"><b>{cash(item.price * quantity)}</b>{item.available ? <div className="detail-order-actions"><div className="detail-quantity" aria-label="Choose quantity"><button aria-label="Remove one" disabled={quantity <= 1} onClick={() => setQuantity((value) => Math.max(1, value - 1))}><Minus size={14}/></button><b>{quantity}</b><button aria-label="Add one" onClick={() => setQuantity((value) => Math.min(50, value + 1))}><Plus size={14}/></button></div><button className="btn btn-primary" onClick={() => { cart.add(item, quantity); onClose(); }}><Plus size={16}/> Add to order</button></div> : <span className="status-chip tone-cancelled">Sold out</span>}</div></div>
      </>}
    </section>
  </div>;
}
function HomePage() {
  const [category, setCategory] = useState('All'); const [search, setSearch] = useState('');
  const [sort, setSort] = useState('popular');
  const params = useMemo(() => ({ ...(category !== 'All' ? { category: category as any } : {}), ...(search.trim() ? { search: search.trim() } : {}) }), [category, search]);
  const menu = useListMenu(params);
  const queue = useGetActiveOrders({ query: { queryKey: getGetActiveOrdersQueryKey(), refetchInterval: 12000 } });
  const items = (menu.data || []) as MenuItem[];
  const sortedItems = useMemo(() => [...items].sort((a, b) => {
    if (sort === 'price-low') return Number(a.price) - Number(b.price) || a.name.localeCompare(b.name);
    if (sort === 'price-high') return Number(b.price) - Number(a.price) || a.name.localeCompare(b.name);
    if (sort === 'name') return a.name.localeCompare(b.name);
    return Number(b.popular) - Number(a.popular) || a.name.localeCompare(b.name);
  }), [items, sort]);
  const popularItems = items.filter((item) => item.popular).slice(0, 3);
  const activeTokens = (queue.data || []) as any[];
  return <div>
    <section className="hero-band"><div className="content-wrap hero-layout"><div className="hero-copy"><div className="hero-note"><Sparkles size={14}/> THE CAMPUS CANTEEN, ON YOUR TIME</div><h1 className="display">Skip the Queue.<br/><span>Order Ahead.</span></h1><p>Browse today’s canteen menu, pre-order your favorites, and pick them up fresh—no waiting in line.</p><a href="#menu" className="btn btn-light hero-cta">See today’s menu <ArrowDownRight size={17}/></a><div className="hero-foot"><span><Clock3 size={15}/> Quick pickup</span><span><Check size={15}/> Made fresh</span><span><CreditCard size={15}/> Pay at counter</span></div></div><div className="hero-art"><div className="sun-disc"/><div className="hero-plate"><div className="plate-food food-rice"/><div className="plate-food food-greens"/><div className="plate-food food-curry"/><div className="plate-food food-crunch"/></div><div className="floating-ticket"><small>YOUR LUNCH BREAK</small><b>Sorted.</b><span>Order now · pick up later</span></div><div className="hero-doodle">GOOD<br/>MOOD<br/>FOOD</div></div></div></section>
    <section className="home-queue"><div className="content-wrap home-queue-inner"><div className="queue-live-mark"><i/> LIVE CANTEEN QUEUE</div><div className="queue-summary">{queue.isError ? 'Live pickup information is temporarily unavailable.' : activeTokens.length ? <><b>{activeTokens.length}</b> active orders in service <span>·</span> Now serving token <strong>#{activeTokens[0].tokenNumber}</strong></> : <><b>All clear</b> at the counter <span>·</span> Be the first to order ahead</>}</div><Link href="/display" className="queue-link">See ready tokens <ArrowRight size={15}/></Link></div></section>
    {popularItems.length > 0 && <section className="content-wrap popular-section"><div className="popular-heading"><div><div className="eyebrow">LOVED AROUND CAMPUS</div><h2 className="display">Today’s popular picks.</h2></div><a href="#menu" className="text-link">Explore the full menu <ArrowDownRight size={15}/></a></div><div className="popular-grid">{popularItems.map((item) => <MenuCard key={`popular-${item.id}`} item={item}/>)}</div></section>}
    <section id="menu" className="content-wrap menu-section"><div className="menu-heading"><div><div className="eyebrow">TODAY AT THE CANTEEN</div><h2 className="display">Find your kind of lunch.</h2></div><div className="menu-controls"><label className="searchbox"><Search size={17}/><input aria-label="Search menu" data-testid="input-menu-search" placeholder="Search dishes" value={search} onChange={(e) => setSearch(e.target.value)}/>{search && <button aria-label="Clear search" onClick={() => setSearch('')}><X size={15}/></button>}</label><label className="sort-control"><span>Sort</span><select aria-label="Sort menu" value={sort} onChange={(e) => setSort(e.target.value)}><option value="popular">Popular</option><option value="name">Name A–Z</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option></select></label></div></div>
      <div className="category-tabs" role="tablist">{categories.map((c) => <button key={c} onClick={() => setCategory(c)} className={category === c ? 'selected' : ''} data-testid={`category-${c.toLowerCase().replaceAll(' ', '-')}`}>{c}</button>)}</div>
      {menu.isLoading ? <div className="food-grid">{[1,2,3,4].map(i => <div className="surface" key={i} style={{ padding: 12 }}><div className="skeleton" style={{ height: 160 }}/><div className="skeleton" style={{ height: 18, marginTop: 15 }}/><div className="skeleton" style={{ height: 42, marginTop: 10 }}/></div>)}</div> : menu.isError ? <QueryNotice error={menu.error} retry={() => menu.refetch()}/> : items.length === 0 ? <div className="empty-menu"><span><CookingPot size={28}/></span><h3>Nothing on this plate yet.</h3><p>Try another search or category. The kitchen may be adding something soon.</p><button className="btn btn-outline" onClick={() => { setSearch(''); setCategory('All'); }}>Show all dishes</button></div> : <div className="food-grid">{sortedItems.map((item) => <MenuCard key={item.id} item={item}/>)}</div>}
    </section>
    <section className="how-section"><div className="content-wrap"><div className="eyebrow">A BETTER BREAK IN THREE STEPS</div><h2 className="display">Good lunch, right on time.</h2><div className="how-grid"><article className="how-card"><span>01</span><Search size={20}/><h3>Pick a favorite</h3><p>Browse the menu, check what’s available, and build your bag.</p></article><article className="how-card"><span>02</span><Clock3 size={20}/><h3>Choose pickup</h3><p>Order for ASAP or choose a time that fits between classes.</p></article><article className="how-card"><span>03</span><Package size={20}/><h3>Collect by token</h3><p>Follow your live order status, then pick up when your token is ready.</p></article></div></div></section>
    <section className="promise-strip"><div className="content-wrap promise-inner"><div className="promise-mark"><Zap size={24}/></div><div><b>More break. Less waiting.</b><p>Place your order between classes. We’ll take it from here.</p></div><Link href="/orders" className="btn btn-ink">Track an order <ArrowRight size={16}/></Link></div></section>
    <Footer/>
  </div>;
}
function Footer() { const health = useHealthCheck(); return <footer className="footer"><div className="content-wrap footer-inner"><div><b className="display">campusbite</b><p>Made for the hungry, hurried, and hard-working.</p></div><div className="footer-links"><Link href="/orders">Your orders</Link><Link href="/profile">Account</Link><Link href="/admin/login">Staff login</Link></div><small>© CampusBite · {health.data?.status ? 'Canteen system online.' : 'Your campus, freshly served.'}</small></div></footer>; }

function CartPage() {
  const cart = useCart();
  if (!cart.lines.length) return <div className="content-wrap"><PageTitle kicker="YOUR BAG" title="A little empty." description="Something delicious is just a few taps away."/><EmptyState title="Nothing in your bag yet" body="Take a look around the menu and add a campus favorite." /></div>;
  return <div className="content-wrap"><PageTitle kicker="YOUR BAG" title="Ready when you are." description={`${cart.count} ${cart.count === 1 ? 'item' : 'items'} from the canteen`} right={<button className="clear-cart" onClick={cart.clear}>Clear bag</button>}/><div className="checkout-grid"><section className="surface cart-lines">{cart.lines.map(({ item, quantity }) => <div className="cart-line" key={item.id} data-testid={`cart-item-${item.id}`}><div className="cart-thumb"><FoodVisual item={item} size="small"/></div><div className="cart-line-title"><b>{item.name}</b><span>{item.category} · {cash(item.price)} each</span></div><div className="cart-qty"><button aria-label={`Decrease ${item.name}`} onClick={() => cart.change(item.id, -1)}><Minus size={14}/></button><b>{quantity}</b><button aria-label={`Increase ${item.name}`} onClick={() => cart.add(item)}><Plus size={14}/></button></div><b className="line-total">{cash(quantity * item.price)}</b><button className="remove-item" aria-label={`Remove ${item.name}`} onClick={() => cart.change(item.id, -quantity)}><Trash2 size={16}/></button></div>)}</section><aside className="surface summary-box"><div className="eyebrow">ORDER SUMMARY</div><h2 className="display">One good lunch.</h2><div className="summary-row"><span>Items ({cart.count})</span><b>{cash(cart.total)}</b></div><div className="summary-row"><span>Pickup fee</span><b>Free</b></div><div className="summary-total"><span>Total</span><b>{cash(cart.total)}</b></div><Link href="/checkout" className="btn btn-primary" style={{ width: '100%', marginTop: 18 }}>Choose pickup time <ArrowRight size={16}/></Link><p className="summary-note"><Check size={14}/> Payment happens at the canteen counter.</p></aside></div></div>;
}
function defaultPickup() { const time = new Date(Date.now() + 20 * 60000); time.setMinutes(Math.ceil(time.getMinutes() / 5) * 5); return new Date(time.getTime() - time.getTimezoneOffset() * 60000).toISOString().slice(0,16); }
function CheckoutPage() {
  const cart = useCart(); const session = useGetSession(); const [pickup, setPickup] = useState(defaultPickup()); const [pickupChoice, setPickupChoice] = useState('ASAP'); const [error, setError] = useState('');
  const place = usePlaceOrder(); const [, navigate] = useLocation();
  const pickupTimestamp = pickupChoice === 'ASAP' ? new Date(Date.now() + 15 * 60000).toISOString() : pickupChoice === 'CUSTOM' ? new Date(pickup).toISOString() : new Date(Date.now() + Number(pickupChoice) * 60000).toISOString();
  if (!cart.lines.length && !place.isSuccess) return <div className="content-wrap"><PageTitle kicker="CHECKOUT" title="Your bag is empty."/><EmptyState title="Start with something tasty" body="Add a dish before choosing pickup." /></div>;
  if (session.isLoading) return <div className="content-wrap"><PageTitle kicker="CHECKOUT" title="Checking your account…"/><LoadingBlock lines={2}/></div>;
  if (!session.data?.user) return <div className="content-wrap"><PageTitle kicker="CHECKOUT" title="Sign in to place your order." description="Your bag will stay here while you sign in."/><div className="checkout-signin surface"><p>Create an account or sign in to save your order and track its pickup token.</p><div><Link href="/login" className="btn btn-primary">Sign in <ArrowRight size={15}/></Link><Link href="/register" className="btn btn-outline">Create account</Link></div></div></div>;
  const submit = (e: FormEvent) => { e.preventDefault(); setError(''); place.mutate({ data: { items: cart.lines.map(({ item, quantity }) => ({ foodItemId: item.id, quantity })), pickupTime: pickupTimestamp, paymentMethod: 'PAY_AT_CANTEEN' } }, { onSuccess: async (order) => { cart.clear(); await queryClient.invalidateQueries({ queryKey: getListMyOrdersQueryKey() }); navigate(`/orders/${order.id}`); }, onError: () => setError('Your order could not be placed. Please review your bag and try again.') }); };
  return <div className="content-wrap"><PageTitle kicker="LAST STEP" title="Make it a pickup." description="Tell us when you’re heading over. We’ll get cooking."/><div className="checkout-grid"><form onSubmit={submit} className="surface checkout-form"><div className="form-section-title"><span>01</span><div><b>Pickup time</b><p>Choose a time that works between classes.</p></div></div><span className="label">I’ll pick up</span><div className="pickup-options">{[['ASAP','ASAP · about 15 min'],['15','In 15 minutes'],['30','In 30 minutes'],['45','In 45 minutes'],['CUSTOM','Choose a time']].map(([value, label]) => <button type="button" key={value} className={`pickup-option ${pickupChoice === value ? 'selected' : ''}`} onClick={() => setPickupChoice(value)}>{label}</button>)}</div>{pickupChoice === 'CUSTOM' && <label className="label" htmlFor="pickup-time">Select pickup date and time <input id="pickup-time" className="field" data-testid="input-pickup-time" type="datetime-local" min={defaultPickup()} value={pickup} required onChange={(e) => setPickup(e.target.value)}/></label>}<div className="pickup-tip"><Clock3 size={16}/> We’ll start preparing your order just in time.</div><div className="form-section-title" style={{ marginTop: 30 }}><span>02</span><div><b>Payment</b><p>Simple, just like the canteen.</p></div></div><div className="payment-choice"><div className="payment-icon"><CreditCard size={20}/></div><div><b>Pay at the canteen</b><small>Cash or card at pickup</small></div><span className="radio-selected"><Check size={12}/></span></div><div className="payment-choice payment-disabled" aria-disabled="true"><div className="payment-icon"><CreditCard size={20}/></div><div><b>Online payment</b><small>Not available yet</small></div><span className="coming-soon">Coming soon</span></div>{error && <p role="alert" style={{ color: '#a83a2d' }}>{error}</p>}<button disabled={place.isPending} className="btn btn-primary" type="submit" style={{ width: '100%', marginTop: 26 }}>{place.isPending ? 'Sending your order…' : 'Place my order'} <ArrowRight size={17}/></button><Link href="/cart" className="back-cart"><ArrowLeft size={14}/> Back to bag</Link></form><aside className="surface summary-box"><div className="eyebrow">YOUR PICKUP ORDER</div><h2 className="display">The good part.</h2>{cart.lines.map(({ item, quantity }) => <div className="summary-row" key={item.id}><span>{quantity} × {item.name}</span><b>{cash(quantity * item.price)}</b></div>)}<div className="summary-total"><span>Total due at pickup</span><b>{cash(cart.total)}</b></div><p className="summary-note"><Check size={14}/> Freshly made after you order.</p></aside></div></div>;
}

function OrdersPage() {
  const session = useGetSession();
  const orders = useListMyOrders({ query: { queryKey: getListMyOrdersQueryKey(), enabled: !!session.data?.user, refetchInterval: 15000 } });
  if (session.isLoading) return <div className="content-wrap"><PageTitle kicker="YOUR CAMPUS BITES" title="Checking your account…"/><LoadingBlock lines={2}/></div>;
  if (!session.data?.user) return <div className="content-wrap"><PageTitle kicker="YOUR CAMPUS BITES" title="Sign in to see your orders."/><div className="checkout-signin surface"><p>Your order history and live pickup tracking are saved to your account.</p><div><Link href="/login" className="btn btn-primary">Sign in <ArrowRight size={15}/></Link><Link href="/register" className="btn btn-outline">Create account</Link></div></div></div>;
  return <div className="content-wrap"><PageTitle kicker="YOUR CAMPUS BITES" title="Order history." description="The past plates, and the ones still on their way."/>
    {orders.isLoading ? <LoadingBlock/> : orders.isError ? <QueryNotice error={orders.error} retry={() => orders.refetch()}/> : !orders.data?.length ? <EmptyState title="Your first order is waiting" body="A favorite meal, a quick snack, a coffee between lectures. Start here."/> : <div className="order-list">{orders.data.map((order) => <Link href={`/orders/${order.id}`} key={order.id} className="order-card surface" data-testid={`order-card-${order.id}`}><div className="order-icon"><Package size={21}/></div><div className="order-main"><span className="eyebrow">ORDER {order.orderNumber}</span><b>{order.items.map((i) => `${i.quantity} × ${i.name}`).join(' · ')}</b><small>{dateShort(order.createdAt)} at {timeShort(order.createdAt)} · pickup {timeShort(order.pickupTime)}</small></div><div className="order-meta"><span className={`status-chip ${statusTone[order.status] || ''}`}>{statusLabel[order.status] || order.status}</span><b>{cash(order.totalAmount)}</b></div><ArrowRight className="order-arrow" size={18}/></Link>)}</div>}</div>;
}
function OrderDetailPage() {
  const { id: rawId } = useParams<{ id: string }>(); const id = Number(rawId);
  const session = useGetSession();
  const orderQuery = useGetOrder(id, { query: { queryKey: getGetOrderQueryKey(id), enabled: !!session.data?.user && Number.isFinite(id) } });
  const live = useGetOrderStatus(id, { query: { queryKey: getGetOrderStatusQueryKey(id), enabled: !!session.data?.user && Number.isFinite(id), refetchInterval: 5000 } });
  const order = orderQuery.data as any;
  if (session.isLoading) return <div className="content-wrap"><PageTitle kicker="ORDER TRACKING" title="Checking your account…"/><LoadingBlock lines={2}/></div>;
  if (!session.data?.user) return <div className="content-wrap"><PageTitle kicker="ORDER TRACKING" title="Sign in to track your order."/><div className="checkout-signin surface"><p>Your token and live pickup status are private to your account.</p><Link href="/login" className="btn btn-primary">Sign in <ArrowRight size={15}/></Link></div></div>;
  if (orderQuery.isLoading) return <div className="content-wrap"><PageTitle kicker="ORDER TRACKING" title="Getting your order…"/><LoadingBlock/></div>;
  if (orderQuery.isError || !order) return <div className="content-wrap"><PageTitle kicker="ORDER TRACKING" title="Order unavailable."/><QueryNotice error={orderQuery.error} retry={() => orderQuery.refetch()}/></div>;
  const status = live.data?.status || order.status;
  const stages = ['PLACED', 'ACCEPTED', 'PREPARING', 'READY', 'COMPLETED']; const activeIndex = stages.indexOf(status);
  return <div className="content-wrap"><Link href="/orders" className="back-cart" style={{ marginTop: 28 }}><ArrowLeft size={14}/> All orders</Link><PageTitle kicker={`ORDER ${order.orderNumber}`} title={status === 'READY' ? 'Your order is ready.' : status === 'CANCELLED' || status === 'REJECTED' ? 'This order is closed.' : 'We’re on it.'} description={`Token #${order.tokenNumber} · Pickup at ${timeShort(order.pickupTime)}`}/><div className="tracking-grid"><section className="surface tracking-card"><div className="tracking-status-head"><div><div className="eyebrow">LIVE ORDER STATUS</div><h2 className="display" data-testid="order-current-status">{statusLabel[status] || status}</h2></div><span className="live-pulse"><i/> LIVE</span></div><div className="status-track">{stages.map((step, i) => <div className={`track-step ${activeIndex >= i ? 'done' : ''} ${activeIndex === i ? 'current' : ''}`} key={step}><span className="track-dot">{activeIndex > i ? <Check size={13}/> : i + 1}</span><div><b>{statusLabel[step]}</b><small>{i === 0 ? 'Order received' : i === 1 ? 'Canteen confirmed' : i === 2 ? 'Freshly prepared' : i === 3 ? 'Come collect it' : 'Enjoy your meal'}</small></div></div>)}</div><p className="tracking-footnote"><Bell size={15}/> This page updates automatically. Keep it handy for pickup.</p></section><aside className="surface token-card"><div className="eyebrow">YOUR PICKUP TOKEN</div><div className="token-number">#{order.tokenNumber}</div><div className="token-date">{dateShort(order.tokenDate)} · {timeShort(order.pickupTime)}</div><div className="token-dash"/><b style={{ display: 'block', marginBottom: 10 }}>In this order</b>{order.items.map((item: any) => <div className="summary-row" key={item.foodItemId}><span>{item.quantity} × {item.name}</span><b>{cash(item.quantity * item.unitPrice)}</b></div>)}<div className="summary-total"><span>Total</span><b>{cash(order.totalAmount)}</b></div><span className="status-chip" style={{ marginTop: 14 }}>{order.paymentMethod === 'PAY_AT_CANTEEN' ? 'Pay at canteen' : order.paymentMethod}</span></aside></div></div>;
}
function ProfilePage() {
  const session = useGetSession(); const logout = useLogout(); const cart = useCart(); const [, navigate] = useLocation();
  if (session.isLoading) return <div className="content-wrap"><PageTitle kicker="YOUR ACCOUNT" title="One moment…"/><LoadingBlock lines={2}/></div>;
  if (!session.data?.user) return <div className="content-wrap"><PageTitle kicker="YOUR ACCOUNT" title="Sign in to see your details."/><Link href="/login" className="btn btn-primary">Sign in <ArrowRight size={16}/></Link></div>;
  const { user } = session.data;
  return <div className="content-wrap"><PageTitle kicker="YOUR ACCOUNT" title={`Hi, ${user.name.split(' ')[0]}.`} description="All your canteen details, in one place."/><div className="profile-layout"><section className="surface profile-card"><div className="profile-avatar">{user.name.slice(0,1).toUpperCase()}</div><div><div className="eyebrow">CAMPUSBITE MEMBER</div><h2 className="display">{user.name}</h2></div><div className="profile-detail"><span>Name</span><b>{user.name}</b></div><div className="profile-detail"><span>Email</span><b>{user.email}</b></div><div className="profile-detail"><span>Phone</span><b>{user.phone || 'Not added'}</b></div><div className="profile-detail"><span>Account type</span><b>{user.role === 'ADMIN' ? 'Canteen staff' : 'Campus customer'}</b></div><button className="btn btn-outline" style={{ marginTop: 24 }} onClick={() => logout.mutate(undefined, { onSuccess: () => { cart.clear(); clearAuthData(); navigate('/'); } })}><LogOut size={16}/> Sign out</button></section><aside className="profile-side"><div className="profile-note"><span><Clock3 size={19}/></span><b>More time for your break</b><p>Order ahead and skip the queue. Your pickup token is always in your order details.</p><Link href="/orders">View your orders <ArrowRight size={14}/></Link></div><div className="profile-note peach"><span><CircleHelp size={19}/></span><b>Need a hand?</b><p>Ask the canteen team about your order at pickup.</p></div></aside></div></div>;
}

function AuthPage({ admin = false, register = false }: { admin?: boolean; register?: boolean }) {
  const registerUser = useRegisterCustomer(); const customerLogin = useLoginCustomer(); const adminLogin = useLoginAdmin();
  const mutation: any = admin ? adminLogin : customerLogin; const [, navigate] = useLocation(); const [error, setError] = useState('');
  const session = useGetSession();
  useEffect(() => { if (session.data?.user) navigate(session.data.user.role === 'ADMIN' ? '/admin' : '/'); }, [session.data, navigate]);
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault(); setError('');
    const form = new FormData(e.currentTarget);
    const onSuccess = (data: any) => { clearAuthData(); queryClient.setQueryData(getGetSessionQueryKey(), data); navigate(admin ? '/admin' : '/'); };
    const onError = () => setError('Those details didn’t work. Check them and try again.');
    if (register) registerUser.mutate({ data: { name: String(form.get('name')), email: String(form.get('email')), password: String(form.get('password')), phone: String(form.get('phone') || '') || null } }, { onSuccess, onError });
    else mutation.mutate({ data: { email: String(form.get('email')), password: String(form.get('password')) } }, { onSuccess, onError });
  };
  const pending = register ? registerUser.isPending : mutation.isPending;
  return (
    <div className="auth-wrap">
      <div className="auth-aside">
        <Link href="/" className="auth-logo"><span><ForkKnife size={20} /></span><b className="display">campusbite</b></Link>
        <div className="auth-aside-copy">
          <div className="eyebrow">{admin ? 'STAFF ACCESS' : 'YOUR CAMPUS CANTEEN'}</div>
          <h1 className="display">{admin ? 'The kitchen is yours.' : 'Good food fits your day.'}</h1>
          <p>{admin ? 'A clear view of every order, every pickup, every plate.' : 'A few taps to your favorite lunch. A whole lot more time to enjoy it.'}</p>
          <div className="auth-quote"><div className="quote-line" /><span>{admin ? 'Keep the line moving.' : 'Freshly made. Right on time.'}</span></div>
        </div>
        <div className="auth-illustration"><div className="auth-orbit" /><Utensils size={74} /><span>FRESH<br />FROM HERE</span></div>
        <small className="auth-copy">A better break starts here.</small>
      </div>
      <div className="auth-panel">
        <div className="auth-mobile-logo"><Link href="/" className="auth-logo"><span><ForkKnife size={20} /></span><b className="display">campusbite</b></Link></div>
        <div className="auth-box">
          <div className="eyebrow">{admin ? 'CANTEEN TEAM' : register ? 'JOIN THE TABLE' : 'WELCOME BACK'}</div>
          <h2 className="display">{admin ? 'Staff sign in' : register ? 'Make it official.' : 'Good to see you.'}</h2>
          <p className="auth-subtitle">{admin ? 'Sign in to manage today’s service.' : register ? 'Create an account and make your next break easier.' : 'Sign in for faster pickup and easy order tracking.'}</p>
          <form onSubmit={submit} className="auth-form">
            {register && <div><label className="label" htmlFor="auth-name">Your name</label><input id="auth-name" name="name" className="field" placeholder="Avery Chen" autoComplete="name" required minLength={1} maxLength={100} /></div>}
            <div><label className="label" htmlFor="auth-email">Email address</label><input id="auth-email" name="email" type="email" className="field" placeholder="you@campus.edu" autoComplete="email" required /></div>
            {register && <div><label className="label" htmlFor="auth-phone">Phone <span style={{ fontWeight: 500, color: '#8c8070' }}>(optional)</span></label><input id="auth-phone" name="phone" type="tel" className="field" placeholder="+91 98765 43210" autoComplete="tel" /></div>}
            <div><label className="label" htmlFor="auth-password">Password</label><input id="auth-password" name="password" type="password" className="field" placeholder={register ? 'At least 8 characters' : 'Enter your password'} autoComplete={register ? 'new-password' : 'current-password'} required minLength={register ? 8 : 1} /></div>
            {error && <div className="auth-error" role="alert">{error}</div>}
            <button type="submit" disabled={pending} className="btn btn-primary" data-testid="button-auth-submit" style={{ width: '100%', marginTop: 4 }}>{pending ? 'One moment…' : admin ? 'Sign in to staff' : register ? 'Create my account' : 'Sign in'} <ArrowRight size={16} /></button>
          </form>
          <div className="auth-switch">{admin ? <Link href="/login">Customer sign in</Link> : register ? <>Already part of the table? <Link href="/login">Sign in</Link></> : <>New around here? <Link href="/register">Create an account</Link></>}</div>
          {!admin && <Link href="/admin/login" className="staff-link">Canteen staff? <span>Staff sign in <ArrowRight size={13} /></span></Link>}
        </div>
        <small className="auth-legal">By continuing, you agree to keep your lunch plans delicious.</small>
      </div>
    </div>
  );
}

const staffNav = [{ href: '/admin', label: 'Overview', icon: LayoutDashboard }, { href: '/admin/orders', label: 'Orders', icon: Package }, { href: '/admin/menu', label: 'Menu', icon: Utensils }, { href: '/admin/analytics', label: 'Analytics', icon: TrendingUp }];
function AdminFrame({ children, title }: { children: ReactNode; title: string }) {
  const [path] = useLocation(); const session = useGetSession(); const logout = useLogout(); const cart = useCart(); const [, navigate] = useLocation();
  if (session.isLoading) return <div className="admin-loading"><LoadingBlock lines={4}/></div>;
  if (!session.data?.user || session.data.user.role !== 'ADMIN') return <div className="admin-denied"><div className="staff-mark"><ChefHat size={26}/></div><div className="eyebrow">STAFF AREA</div><h1 className="display">This counter is for staff.</h1><p>Sign in with your canteen team account to continue.</p><Link className="btn btn-primary" href="/admin/login">Staff sign in <ArrowRight size={16}/></Link><Link className="back-cart" href="/">Back to CampusBite</Link></div>;
  return <div className="admin-layout"><aside className="admin-sidebar"><Link href="/admin" className="admin-brand"><span><ForkKnife size={19}/></span><b className="display">campus<span>bite</span></b></Link><div className="staff-profile"><div className="staff-avatar">{session.data.user.name[0]}</div><div><b>{session.data.user.name}</b><small>Canteen team</small></div><span className="online-dot"/></div><div className="sidebar-label">SERVICE DESK</div><nav>{staffNav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} className={`staff-nav ${path === href ? 'active' : ''}`}><Icon size={18}/>{label}{href === '/admin/orders' && <i className="nav-live"/>}</Link>)}</nav><div className="sidebar-bottom"><Link href="/kitchen" className="staff-nav"><CookingPot size={18}/>Kitchen screen <ArrowUpRight size={13}/></Link><Link href="/display" className="staff-nav"><Eye size={18}/>Ready display <ArrowUpRight size={13}/></Link><button className="staff-nav" onClick={() => logout.mutate(undefined, { onSuccess: () => { cart.clear(); clearAuthData(); navigate('/admin/login'); } })}><LogOut size={18}/>Sign out</button></div></aside><main className="admin-main"><header className="admin-topbar"><div><span className="admin-breadcrumb">CAMPUSBITE <span>/</span> {title.toUpperCase()}</span><b>{title}</b></div><div className="admin-top-right"><span className="service-indicator"><i/> Service live</span><span className="admin-avatar">{session.data.user.name[0]}</span></div></header><div className="admin-content page-enter">{children}</div></main></div>;
}
function StatCard({ label, value, icon: Icon, note, tone = '' }: { label: string; value: string | number; icon: any; note?: string; tone?: string }) {
  return (
    <div className={`stat-card ${tone}`}>
      <div className="stat-top"><span>{label}</span><i><Icon size={18} /></i></div>
      <b>{value}</b>
      {note && <small>{note}</small>}
    </div>
  );
}
function AdminDashboardPage() {
  const dash = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey(), refetchInterval: 12000 } }); const data = dash.data as any;
  return <AdminFrame title="Overview"><div className="admin-welcome"><div><div className="eyebrow">TODAY'S SERVICE</div><h1 className="display">Let’s make it a good one.</h1><p>{new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' })} · Live view refreshes automatically</p></div><Link href="/admin/orders" className="btn btn-ink"><Activity size={16}/> Open order queue <ArrowRight size={15}/></Link></div>
    {dash.isLoading ? <LoadingBlock lines={3}/> : dash.isError ? <QueryNotice error={dash.error} retry={() => dash.refetch()}/> : <><div className="stat-grid"><StatCard label="Orders today" value={data.todayOrders} icon={ShoppingBag} note={`${data.pendingOrders} waiting for a start`} tone="stat-peach"/><StatCard label="In the kitchen" value={data.preparingOrders} icon={CookingPot} note="Currently being prepared" tone="stat-green"/><StatCard label="Ready to collect" value={data.readyOrders} icon={Bell} note="Tokens to call out" tone="stat-yellow"/><StatCard label="Today's revenue" value={cash(data.revenueToday)} icon={TrendingUp} note={`${data.completedOrders} completed orders`} tone="stat-cream"/></div><div className="admin-dashboard-columns"><section className="admin-panel"><div className="panel-heading"><div><div className="eyebrow">PICKUP QUEUE</div><h2 className="display">Active tokens</h2></div><Link href="/admin/orders" className="panel-link">All orders <ArrowRight size={14}/></Link></div>{data.activeTokens?.length ? <div className="mini-token-list">{data.activeTokens.slice(0,5).map((token: any) => <div className="mini-token" key={token.id}><b>#{token.tokenNumber}</b><div>{token.items?.map((i: any) => `${i.quantity} × ${i.name}`).join(', ')}</div><span className={`status-chip ${statusTone[token.status]}`}>{statusLabel[token.status]}</span></div>)}</div> : <div className="admin-empty"><Package size={23}/><b>No active tokens yet</b><span>New orders will show up here.</span></div>}</section><section className="service-card"><div className="service-sun"><ChefHat size={25}/></div><div className="eyebrow">A GOOD SERVICE</div><h2 className="display">One order at a time.</h2><p>Keep the queue moving, make it fresh, and let the pickup screen do the talking.</p><Link href="/kitchen" className="btn btn-light">Open kitchen screen <ArrowRight size={15}/></Link></section></div></>}</AdminFrame>;
}
function AdminOrdersPage() {
  const orders = useListAdminOrders({ query: { queryKey: getListAdminOrdersQueryKey(), refetchInterval: 7000 } }); const update = useUpdateOrderStatus();
  const [filter, setFilter] = useState('ACTIVE'); const [busyId, setBusyId] = useState<number | null>(null);
  const all = (orders.data || []) as any[];
  const filtered = all.filter((o) => filter === 'ALL' || (filter === 'ACTIVE' ? !['COMPLETED','CANCELLED','REJECTED'].includes(o.status) : o.status === filter));
  const advance: Record<string, string> = { PLACED: 'ACCEPTED', ACCEPTED: 'PREPARING', PREPARING: 'READY', READY: 'COMPLETED' };
  const updateStatus = (order: any, status: string) => { setBusyId(order.id); update.mutate({ id: order.id, data: { status: status as any } }, { onSettled: () => setBusyId(null), onSuccess: async () => { await Promise.all([queryClient.invalidateQueries({ queryKey: getListAdminOrdersQueryKey() }), queryClient.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }), queryClient.invalidateQueries({ queryKey: getGetActiveOrdersQueryKey() }), queryClient.invalidateQueries({ queryKey: getGetReadyTokensQueryKey() })]); } }); };
  return <AdminFrame title="Orders"><div className="staff-page-heading"><div><div className="eyebrow">THE SERVICE QUEUE</div><h1 className="display">Orders, in motion.</h1><p>Accept, prepare, and call out each pickup as it happens.</p></div><span className="live-pulse"><i/> AUTO REFRESH</span></div>
    <div className="order-toolbar"><div className="order-filters">{['ACTIVE','PLACED','PREPARING','READY','COMPLETED','CANCELLED','REJECTED','ALL'].map((f) => <button key={f} className={filter === f ? 'active' : ''} onClick={() => setFilter(f)}>{f === 'ACTIVE' ? 'Active' : f === 'ALL' ? 'All orders' : statusLabel[f]}</button>)}</div><span>{filtered.length} orders</span></div>
    {orders.isLoading ? <LoadingBlock/> : orders.isError ? <QueryNotice error={orders.error} retry={() => orders.refetch()}/> : !filtered.length ? <div className="admin-empty panel-empty"><Package size={26}/><b>Nothing in this queue.</b><span>New orders will appear here automatically.</span></div> : <div className="staff-order-list">{filtered.map((order) => <article className="staff-order" key={order.id} data-testid={`admin-order-${order.id}`}><div className="staff-order-primary"><div className="staff-token">#{order.tokenNumber}</div><div><div className="staff-order-ref">{order.orderNumber} <span>· {timeShort(order.createdAt)}</span></div><b>{order.customerName || 'Campus customer'}</b><small>Pickup {timeShort(order.pickupTime)} · {order.items.map((i: any) => `${i.quantity} × ${i.name}`).join(', ')}</small></div></div><div className="staff-order-meta"><span className={`status-chip ${statusTone[order.status] || ''}`}>{statusLabel[order.status] || order.status}</span><b>{cash(order.totalAmount)}</b></div><div className="staff-order-actions">{advance[order.status] && <button className="btn btn-primary" disabled={busyId === order.id} onClick={() => updateStatus(order, advance[order.status])}>{busyId === order.id ? 'Updating…' : order.status === 'PLACED' ? 'Accept order' : order.status === 'ACCEPTED' ? 'Start cooking' : order.status === 'PREPARING' ? 'Mark ready' : 'Complete pickup'} <ArrowRight size={14}/></button>}{order.status === 'PLACED' && <button className="reject-button" disabled={busyId === order.id} onClick={() => { if (window.confirm(`Reject order ${order.orderNumber}?`)) updateStatus(order, 'REJECTED'); }}>Reject</button>}{['PLACED','ACCEPTED'].includes(order.status) && <button className="reject-button" disabled={busyId === order.id} onClick={() => { if (window.confirm(`Cancel order ${order.orderNumber}?`)) updateStatus(order, 'CANCELLED'); }}>Cancel</button>}</div></article>)}</div>}</AdminFrame>;
}
const foodCategories = ['Breakfast','Meals','Snacks','Fast Food','Drinks','Desserts'];
function AdminMenuPage() {
  const menu = useListMenu(); const create = useCreateMenuItem(); const update = useUpdateMenuItem(); const remove = useDeleteMenuItem();
  const [editing, setEditing] = useState<any | null>(null); const [showForm, setShowForm] = useState(false); const [error, setError] = useState('');
  const items = (menu.data || []) as MenuItem[];
  const openAdd = () => { setEditing(null); setShowForm(true); setError(''); };
  const save = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setError(''); const form = new FormData(e.currentTarget); const payload = { name: String(form.get('name')), description: String(form.get('description')), price: Number(form.get('price')), category: String(form.get('category')) as any, imageUrl: String(form.get('imageUrl') || '') || null, isVegetarian: form.get('vegetarian') === 'on', available: form.get('available') === 'on', popular: form.get('popular') === 'on' }; const options = { onSuccess: async () => { setShowForm(false); setEditing(null); await queryClient.invalidateQueries({ queryKey: getListMenuQueryKey() }); }, onError: () => setError('Could not save this dish. Please check the details and try again.') }; if (editing) update.mutate({ id: editing.id, data: payload }, options); else create.mutate({ data: payload }, options); };
  const toggleAvailability = (item: MenuItem) => update.mutate({ id: item.id, data: { available: !item.available } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMenuQueryKey() }) });
  return <AdminFrame title="Menu"><div className="staff-page-heading"><div><div className="eyebrow">WHAT'S COOKING</div><h1 className="display">The menu board.</h1><p>Keep today’s lineup fresh and easy to order.</p></div><button className="btn btn-primary" onClick={openAdd}><Plus size={17}/> Add a dish</button></div>
    {menu.isLoading ? <LoadingBlock/> : menu.isError ? <QueryNotice error={menu.error} retry={() => menu.refetch()}/> : !items.length ? <div className="admin-empty panel-empty"><Utensils size={26}/><b>Your menu is ready for its first dish.</b><span>Add a dish and it will appear here.</span><button className="btn btn-primary" onClick={openAdd}><Plus size={15}/> Add a dish</button></div> : <div className="menu-table-wrap"><table className="menu-table"><thead><tr><th>Dish</th><th>Category</th><th>Price</th><th>Dietary</th><th>Availability</th><th></th></tr></thead><tbody>{items.map((item) => <tr key={item.id} data-testid={`menu-row-${item.id}`}><td><div className="table-dish"><span><FoodVisual item={item} size="small"/></span><div><b>{item.name}</b><small>{item.popular ? 'Popular choice' : item.description}</small></div></div></td><td>{item.category}</td><td><b>{cash(item.price)}</b></td><td>{item.isVegetarian ? <span className="veg-tag"><Leaf size={13}/> Vegetarian</span> : <span className="muted-tag">Regular</span>}</td><td><button className={`availability ${item.available ? 'is-on' : ''}`} onClick={() => toggleAvailability(item)}><i/>{item.available ? 'Available' : 'Sold out'}</button></td><td><div className="table-actions"><button title="Edit dish" aria-label={`Edit ${item.name}`} onClick={() => { setEditing(item); setShowForm(true); setError(''); }}><Settings2 size={16}/></button><button title="Delete dish" aria-label={`Delete ${item.name}`} onClick={() => { if (window.confirm(`Remove ${item.name} from the menu?`)) remove.mutate({ id: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMenuQueryKey() }) }); }}><Trash2 size={16}/></button></div></td></tr>)}</tbody></table></div>}
    {showForm && <div className="modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) setShowForm(false); }}><form className="menu-modal" onSubmit={save}><div className="modal-heading"><div><div className="eyebrow">{editing ? 'MENU EDITOR' : 'NEW TO THE LINEUP'}</div><h2 className="display">{editing ? 'Tweak this dish.' : 'Add a dish.'}</h2></div><button type="button" aria-label="Close form" className="modal-close" onClick={() => setShowForm(false)}><X size={19}/></button></div><div className="modal-fields"><label><span className="label">Dish name</span><input className="field" name="name" defaultValue={editing?.name || ''} maxLength={120} required/></label><label><span className="label">Price</span><input className="field" name="price" type="number" min="0" step=".01" defaultValue={editing?.price ?? ''} required/></label><label className="span-two"><span className="label">Description</span><textarea className="field" name="description" rows={3} maxLength={1000} defaultValue={editing?.description || ''} required/></label><label><span className="label">Category</span><select className="field" name="category" defaultValue={editing?.category || 'Meals'}>{foodCategories.map(c => <option key={c} value={c}>{c}</option>)}</select></label><label><span className="label">Image URL <small>(optional)</small></span><input className="field" name="imageUrl" type="url" defaultValue={editing?.imageUrl || ''} placeholder="https://…"/></label><label className="check-field"><input name="vegetarian" type="checkbox" defaultChecked={editing?.isVegetarian || false}/> Vegetarian</label><label className="check-field"><input name="available" type="checkbox" defaultChecked={editing ? editing.available : true}/> Available to order</label><label className="check-field"><input name="popular" type="checkbox" defaultChecked={editing?.popular || false}/> Popular today</label></div>{error && <p role="alert" style={{ color: '#a83a2d' }}>{error}</p>}<div className="modal-footer"><button type="button" className="btn btn-outline" onClick={() => setShowForm(false)}>Cancel</button><button type="submit" className="btn btn-primary" disabled={create.isPending || update.isPending}>{create.isPending || update.isPending ? 'Saving…' : editing ? 'Save changes' : 'Add to menu'} <Check size={15}/></button></div></form></div>}
  </AdminFrame>;
}
function AnalyticsPage() {
  const q = useGetAnalytics(); const a = q.data as any;
  return <AdminFrame title="Analytics"><div className="staff-page-heading"><div><div className="eyebrow">THE BIG PICTURE</div><h1 className="display">How service is going.</h1><p>Useful signals for a better day at the counter.</p></div><span className="analytics-date"><Activity size={15}/> Today so far</span></div>
    {q.isLoading ? <LoadingBlock lines={3}/> : q.isError ? <QueryNotice error={q.error} retry={() => q.refetch()}/> : <><div className="stat-grid analytics-stats"><StatCard label="Orders today" value={a.totalOrdersToday} icon={ShoppingBag} note="Orders placed today" tone="stat-peach"/><StatCard label="Revenue today" value={cash(a.revenueToday)} icon={TrendingUp} note="Gross canteen sales" tone="stat-green"/><StatCard label="Orders this week" value={a.ordersThisWeek} icon={Activity} note="A rolling seven-day view" tone="stat-yellow"/><StatCard label="Average order" value={cash(a.averageOrderValue)} icon={CreditCard} note="Per order, all week" tone="stat-cream"/></div><div className="analytics-panels"><section className="admin-panel analytics-panel"><div className="panel-heading"><div><div className="eyebrow">WHAT'S MOVING</div><h2 className="display">Best sellers</h2></div><span className="analytics-date">This week</span></div>{a.bestSellingItems?.length ? <div className="bar-list">{a.bestSellingItems.map((item: any, i: number) => { const max = Math.max(...a.bestSellingItems.map((x: any) => x.quantity), 1); return <div className="bar-row" key={item.name}><div className="bar-row-top"><span><i>{String(i + 1).padStart(2,'0')}</i>{item.name}</span><b>{item.quantity} sold</b></div><div className="bar-track"><div style={{ width: `${Math.max(6, item.quantity / max * 100)}%` }}/></div></div>; })}</div> : <div className="admin-empty"><Flame size={21}/><b>Sales are warming up.</b><span>Best sellers show once orders roll in.</span></div>}</section><section className="admin-panel analytics-panel"><div className="panel-heading"><div><div className="eyebrow">THE MENU MIX</div><h2 className="display">Orders by category</h2></div></div>{a.ordersByCategory?.length ? <div className="category-sales">{a.ordersByCategory.map((item: any, i: number) => { const max = Math.max(...a.ordersByCategory.map((x: any) => x.orders), 1); return <div className="category-sale" key={item.category}><div className="category-sale-head"><span><i className={`category-swatch swatch-${i % 5}`}/>{item.category}</span><b>{item.orders}</b></div><div className="bar-track"><div className={`category-bar bar-${i % 5}`} style={{ width: `${Math.max(5, item.orders / max * 100)}%` }}/></div></div>; })}</div> : <div className="admin-empty"><Tag size={21}/><b>No category data yet.</b><span>It’ll take shape as orders come in.</span></div>}</section></div></>}</AdminFrame>;
}
function KitchenPage() {
  const session = useGetSession(); const q = useGetActiveOrders({ query: { queryKey: getGetActiveOrdersQueryKey(), refetchInterval: 5000 } }); const update = useUpdateOrderStatus(); const orders = (q.data || []) as any[];
  if (session.isLoading) return <div className="kitchen-loading"><LoadingBlock/></div>;
  if (!session.data?.user || session.data.user.role !== 'ADMIN') return <div className="admin-denied"><ChefHat size={30}/><h1 className="display">Staff access only</h1><Link className="btn btn-primary" href="/admin/login">Sign in to the kitchen</Link></div>;
  const advance: Record<string, string> = { PLACED: 'ACCEPTED', ACCEPTED: 'PREPARING', PREPARING: 'READY' };
  const labels: Record<string,string> = { PLACED: 'Accept order', ACCEPTED: 'Start cooking', PREPARING: 'Mark ready' };
  const preparingOrders = orders.filter((order) => order.status !== 'READY');
  const readyOrders = orders.filter((order) => order.status === 'READY');
  const renderTicket = (order: any) => <article className="kitchen-ticket" key={order.id}><header><span>TOKEN <b>#{order.tokenNumber}</b></span><span>{timeShort(order.createdAt)}</span></header><div className="kitchen-customer">{order.customerName || 'Campus customer'}</div><div className="kitchen-items">{order.items.map((line: any) => <div key={line.foodItemId}><b>{line.quantity}</b><span>{line.name}</span></div>)}</div><div className="kitchen-ticket-foot"><span className={`status-chip ${statusTone[order.status]}`}>{statusLabel[order.status]}</span>{advance[order.status] && <button className="btn btn-primary" onClick={() => update.mutate({ id: order.id, data: { status: advance[order.status] as any } }, { onSuccess: () => Promise.all([queryClient.invalidateQueries({ queryKey: getGetActiveOrdersQueryKey() }), queryClient.invalidateQueries({ queryKey: getListAdminOrdersQueryKey() }), queryClient.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }), queryClient.invalidateQueries({ queryKey: getGetReadyTokensQueryKey() })]) })}>{labels[order.status]} <ArrowRight size={14}/></button>}</div></article>;
  return <div className="kitchen-screen"><header className="kitchen-header"><Link href="/admin" className="kitchen-logo"><span><ForkKnife size={18}/></span><b className="display">campusbite <i>/ KITCHEN</i></b></Link><div className="kitchen-live"><i/> LIVE ORDERS</div><span className="kitchen-time">{new Date().toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' })}</span></header><div className="kitchen-intro"><div><div className="eyebrow">THE PASS</div><h1 className="display">Cook. Call. Keep it moving.</h1></div><span>{orders.length} active {orders.length === 1 ? 'order' : 'orders'}</span></div>{q.isLoading ? <LoadingBlock lines={3}/> : q.isError ? <QueryNotice error={q.error} retry={() => q.refetch()}/> : orders.length === 0 ? <div className="kitchen-empty"><CookingPot size={37}/><h2 className="display">A quiet moment in the kitchen.</h2><p>New orders will appear as soon as they come in.</p></div> : <div className="kitchen-columns"><section className="kitchen-column"><header><div><span className="eyebrow">PREPARATION</span><h2 className="display">In the kitchen</h2></div><b>{preparingOrders.length}</b></header>{preparingOrders.length ? <div className="kitchen-board">{preparingOrders.map(renderTicket)}</div> : <div className="kitchen-column-empty">No orders waiting to be prepared.</div>}</section><section className="kitchen-column ready-column"><header><div><span className="eyebrow">PICKUP</span><h2 className="display">Ready to collect</h2></div><b>{readyOrders.length}</b></header>{readyOrders.length ? <div className="kitchen-board">{readyOrders.map(renderTicket)}</div> : <div className="kitchen-column-empty">Ready orders will appear here.</div>}</section></div>}</div>;
}
function DisplayPage() {
  const q = useGetReadyTokens({ query: { queryKey: getGetReadyTokensQueryKey(), refetchInterval: 5000 } }); const tokens = (q.data || []) as any[];
  return <div className="display-screen"><header><Link href="/" className="display-brand"><span><ForkKnife size={20}/></span><b className="display">campusbite</b></Link><div><span className="display-live"><i/> LIVE PICKUPS</span><span className="display-clock">{new Date().toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' })}</span></div></header><main><div className="display-kicker">CANTEEN PICKUP BOARD</div><h1 className="display">Ready for you.</h1><p>Listen for your token. Come collect something good.</p>{q.isLoading ? <div className="display-token-grid">{[1,2,3].map(i => <div className="display-skeleton" key={i}/>)}</div> : q.isError ? <div className="display-empty"><CircleHelp size={25}/><b>Pickup board unavailable</b><button className="btn btn-light" onClick={() => q.refetch()}>Try again</button></div> : tokens.length ? <div className="display-token-grid">{tokens.map((token) => <article className="ready-token" key={token.id} data-testid={`ready-token-${token.tokenNumber}`}><span>TOKEN</span><b>#{token.tokenNumber}</b><small>{token.items?.map((item: any) => `${item.quantity} × ${item.name}`).join(' · ')}</small><i><Check size={15}/> READY NOW</i></article>)}</div> : <div className="display-empty"><span><CookingPot size={31}/></span><b>Nothing ready just yet.</b><p>We’ll call your token as soon as your order is ready.</p></div>}</main><footer><span>FRESH FROM THE CANTEEN</span><span>THANK YOU FOR ORDERING CAMPUSBITE</span></footer></div>;
}
function NotFoundPage() { return <div className="content-wrap"><PageTitle kicker="WRONG TURN" title="That plate isn’t on the menu." description="The page you’re looking for may have moved."/><Link href="/" className="btn btn-primary">Back to the menu <ArrowRight size={15}/></Link></div>; }

function Router() {
  return <Switch>
    <Route path="/login"><AuthPage/></Route><Route path="/register"><AuthPage register/></Route><Route path="/admin/login"><AuthPage admin/></Route>
    <Route path="/kitchen"><KitchenPage/></Route><Route path="/display"><DisplayPage/></Route>
    <Route path="/admin"><AdminDashboardPage/></Route><Route path="/admin/orders"><AdminOrdersPage/></Route><Route path="/admin/menu"><AdminMenuPage/></Route><Route path="/admin/analytics"><AnalyticsPage/></Route>
    <Route path="/orders/:id"><Shell><OrderDetailPage/></Shell></Route><Route path="/orders"><Shell><OrdersPage/></Shell></Route>
    <Route path="/cart"><Shell><CartPage/></Shell></Route><Route path="/checkout"><Shell><CheckoutPage/></Shell></Route><Route path="/profile"><Shell><ProfilePage/></Shell></Route>
    <Route path="/"><Shell><HomePage/></Shell></Route><Route><NotFoundPage/></Route>
  </Switch>;
}
function App() {
  return <QueryClientProvider client={queryClient}><CartProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router/></WouterRouter><div className="noise"/></CartProvider></QueryClientProvider>;
}
export default App;
